// Calculate base risk from cryptocurrency type
let cryptoRisk = 0;
switch(primaryCrypto) {
  case 'bitcoin': cryptoRisk = 70; break;
  case 'ethereum': cryptoRisk = 75; break;
  case 'monero': cryptoRisk = 20; break;
  case 'zcash': cryptoRisk = 35; break;
  case 'litecoin': cryptoRisk = 70; break;
  default: cryptoRisk = 65;
}

// Frequency multiplier
let freqMultiplier = Math.min(transactionFrequency / 10, 2);

// Exchange risk
let exchangeRisk = 0;
switch(exchangeType) {
  case 'centralized': exchangeRisk = 40; break;
  case 'decentralized': exchangeRisk = 15; break;
  case 'both': exchangeRisk = 25; break;
  case 'p2p': exchangeRisk = 10; break;
  case 'none': exchangeRisk = 0; break;
}

// Address reuse risk
let reuseRisk = 0;
switch(walletReuse) {
  case 'never': reuseRisk = 0; break;
  case 'rarely': reuseRisk = 10; break;
  case 'sometimes': reuseRisk = 25; break;
  case 'often': reuseRisk = 40; break;
  case 'always': reuseRisk = 60; break;
}

// Privacy tools reduction
let privacyReduction = privacyTools ? -20 : 0;

// Browser privacy impact
let browserRisk = 0;
switch(browserPrivacy) {
  case 'standard': browserRisk = 30; break;
  case 'private': browserRisk = 20; break;
  case 'incognito-browser': browserRisk = 5; break;
  case 'tor': browserRisk = 0; break;
  case 'vpn': browserRisk = 10; break;
}

// KYC risk
let kycRisk = kycCompliance * 8;

// Public disclosure risk
let disclosureRisk = 0;
switch(publicDisclosure) {
  case 'never': disclosureRisk = 0; break;
  case 'social': disclosureRisk = 30; break;
  case 'business': disclosureRisk = 20; break;
  case 'forums': disclosureRisk = 25; break;
  case 'multiple': disclosureRisk = 50; break;
}

// Calculate overall risk
let baseRisk = (cryptoRisk + exchangeRisk + reuseRisk + browserRisk + kycRisk + disclosureRisk) / 6;
let overallRisk = Math.max(0, Math.min(100, baseRisk * freqMultiplier + privacyReduction));

// Determine risk level
let riskLevel = '';
if(overallRisk <= 25) riskLevel = 'A';
else if(overallRisk <= 45) riskLevel = 'B';
else if(overallRisk <= 65) riskLevel = 'C';
else if(overallRisk <= 80) riskLevel = 'D';
else riskLevel = 'F';

// Calculate anonymity and exposure
let anonymityScore = Math.max(0, 100 - overallRisk);
let exposureRisk = Math.min(100, overallRisk + (kycRisk * 0.5) + (disclosureRisk * 0.3));

return {
  overallRisk: Math.round(overallRisk),
  riskLevel: riskLevel,
  anonymityScore: Math.round(anonymityScore),
  exposureRisk: Math.round(exposureRisk)
};
